// The fleet-steward plugin's contract (issue #3115, EPIC #3111 C4): what
// panels-model.ts folds out of the steward's books, and the values its mod
// module keeps in $.state. Moved here from the core mod's types (mod/fleet).

// The orchestrator's / steward's panels (issue #2835): what panels-model.ts
// folds out of the books.

export type SheetRow = {
  id: string
  item: string
  suggest: string
  default: string
  due: string
  kind: string
  src: string
  url: string
  state: string
  by: string
  asked: string
}

export type Sheet = { id: string; at: string; where: string; sent: boolean; rows: SheetRow[] }

/** One ask behind a group: its own words (the panel's 原话). */
export type SheetAsk = { id: string; item: string; asked: string; url: string }

/**
 * One line of the decision sheet's panel (issue #2832): fleet_decision.group's
 * output, kept by the steward as `groups` in steward.state.json — the panel
 * never merges on its own. `gid` is the latest ask's row id, `ids` every row it
 * answers; `default` / `dueShow` are already the words to draw.
 */
export type SheetGroup = {
  gid: string
  ids: string[]
  item: string
  suggest: string
  default: string
  due: string
  dueShow: string
  kind: string
  never: boolean
  src: string
  url: string
  from: string
  state: string
  by: string
  answer: string
  closedAt: string
  asked: string
  asks: SheetAsk[]
}

/** An answer pressed and not sent yet: it waits UNDO_MS for `u`. */
export type SheetPending = { ids: string[]; text: string; how: 'take' | 'turn'; at: number; presses: number }

/** The `{plugin:'fleet', key:'sheet'}` state: the panel's own, never the books'. */
export type SheetUi = {
  pending: Record<string, SheetPending>
  /** The group whose 翻案 field is open ('' none). */
  editing: string
  /** The group whose 原话 are shown ('' none). */
  expanded: string
  /** Groups being written back right now. */
  sending: string[]
  /** Presses on a group since it was last answered (the metric's 按几下). */
  presses: Record<string, number>
}

export type Batch = {
  repo: string
  epic: number
  tick: number
  landed: number
  members: number
  /** null: a mark written before the heartbeat carried the reading (#2247). */
  live: number | null
  inflight: number | null
  epoch: number
  ttl: number
  fresh: boolean
  /** The mark's `title:` line (issue #2833); '' on a mark from before it. */
  title: string
}

export type Parked = { ref: string; at: number; wait: string[]; key: string }

export type QueueRow = { child: string; state: string; verdict: string }

export type Patrol = {
  beat: number
  at: string
  changed: boolean
  writes: number
  nextAt: number
  card: string[]
  modelCalls: number
  parked: Parked[]
  newAsks: number
  closed: number
  defaulted: number
  /** The rest of what the patrol panel shows (issue #2834). */
  drivers: number
  openRows: number
  events: number
  /** Today's closes (the beat's local day): answered by the steward, by their default. */
  bySteward: number
  byDefault: number
  /** What is handed to the person: open sheet groups (a row's `group`, else one a row). */
  groups: number
  health: number
  /** The newest active health finding's first sentence ('' when none). */
  healthTop: string
  deferred: number
  /** The steward page's URL ('' when none). */
  page: string
  /** Sessions past their reap policy and still open (issue #3352, bin/fleet-reap-overdue.py);
   *  how many of those are stuck > 30 min, and the longest-stuck one's line. */
  overdue: number
  overdueStuck: number
  overdueTop: string
}

export type Todo = { open: number; desk: string }

/** One batch on the batches pane (issue #2833): a mark, or a driver the ledger still has going with no mark. */
export type BoardBatch = Batch & {
  /** `<repo>#<N>`, or `#<N>` with no repo. */
  ref: string
  /** The driver's key off the steward's `drivers` book; '' when it names none. */
  driver: string
  /** Sessions of this batch the steward parked (park.json, by their origin). */
  parked: number
  /** No mark at all: the ledger says the driver is going, the progress cannot be read. */
  noMark: boolean
}

/** A batch the steward saw close today (its `todo.epics` row `done`). */
export type BoardDone = { ref: string; epic: number; title: string }

/** One open row of the steward's 「待你动手」 list (`todo.items`). */
export type BoardTodo = { id: string; kind: string; what: string; due: string; url: string }

export type Board = { batches: BoardBatch[]; done: BoardDone[]; todo: BoardTodo[] }

/** The `{plugin:'fleet-steward', key:'panels'}` state (EPIC #2831's interface). */
export type PanelsView = {
  sheet: Sheet | null
  /** The decision sheet's lines, open first (issue #2832); [] from a steward before it. */
  groups: SheetGroup[]
  batches: Batch[]
  todo: Todo
  queue: QueueRow[]
  patrol: Patrol
  /** The batches pane's rows (issue #2833). */
  board: Board
  /** When this view was read (epoch ms). */
  at: number
  /** How long the read took (ms). */
  ms: number
}

declare module 'claude-code' {
  interface PluginState {
    'fleet-steward': {
      /** What the panels last read from the books (issue #2835); null before the first read. */
      panels: PanelsView | null
      /** The decision sheet's own state (issue #2832). */
      sheet: SheetUi
      /** Bumped on each open / close of the decision sheet (issue #2836): the band's hint redraws. */
      sheetPane: number
    }
  }
}
